// Merge test cases + test data into one Test Pack, and compute the current revision count.
const storyInfo = $('Format Jira Story Text').item.json;
const tcOut = $('AI Test Case Generator').item.json.output;
const dataOut = $input.item.json.output;

let revisionCount = 0;
try {
  const prevCtx = $('Prepare Revision Context').first();
  if (prevCtx && prevCtx.json && typeof prevCtx.json.revisionCount === 'number') {
    revisionCount = prevCtx.json.revisionCount;
  }
} catch (e) {
  revisionCount = 0;
}
const maxRevisions = 3;

const testCases = tcOut.testCases || [];
const testData = dataOut.testData || [];
const dataByCaseId = {};
for (const td of testData) {
  dataByCaseId[td.testCaseId] = td.fields;
}

let md = `Jira Issue: ${storyInfo.issueKey} - ${storyInfo.summary}\n\n`;

if (tcOut.decision === 'Denied') {
  md += `Decision: Denied\nReason: ${tcOut.reason}\n`;
} else {
  for (const tc of testCases) {
    md += `[${tc.id}] ${tc.title} (${tc.type} / ${tc.priority})\n`;
    md += `Preconditions: ${tc.preconditions}\n`;
    md += `Steps: ${tc.steps}\n`;
    md += `Expected Result: ${tc.expectedResult}\n`;
    md += `Data Needed: ${tc.dataNeeded}\n`;
    const fields = dataByCaseId[tc.id];
    if (fields && fields.length > 0) {
      for (const f of fields) {
        if (f.valid && f.valid.length) md += `  - ${f.fieldName} (valid): ${f.valid.join(', ')}\n`;
        if (f.invalid && f.invalid.length) md += `  - ${f.fieldName} (invalid): ${f.invalid.join(', ')}\n`;
        if (f.boundaryEdge && f.boundaryEdge.length) md += `  - ${f.fieldName} (boundary/edge): ${f.boundaryEdge.join(', ')}\n`;
      }
    }
    md += `\n`;
  }
}

return [{
  json: {
    issueKey: storyInfo.issueKey,
    summary: storyInfo.summary,
    decision: tcOut.decision,
    reason: tcOut.reason,
    testCases,
    testData,
    testPackText: md,
    revisionCount,
    maxRevisions
  }
}];

