// Build the form payload for human approval. Runs every loop iteration.
const pack = $('Merge Test Pack').item.json;
const review = $input.item.json.output;

let issuesText = '(No issues found)';
if (review.issues && review.issues.length) {
  issuesText = review.issues.map(i => `[${i.id}] (${i.relatedTestCaseId} | ${i.dimension}/${i.severity}) ${i.comment}`).join('\n');
}

return [{
  json: {
    issueKey: pack.issueKey,
    summary: pack.summary,
    testPackText: pack.testPackText,
    reviewVerdict: review.overallVerdict,
    reviewSummary: review.summary,
    reviewIssuesText: issuesText,
    revisionCount: pack.revisionCount,
    maxRevisions: pack.maxRevisions
  }
}];

const form = $input.item.json;

const revisionCount = Number(form['Revision Count']) || 0;
const maxRevisions = Number(form['Max Revisions']) || 3;
const comment = (form['Revision Comments'] || '').toString().trim();
const hasComment = comment.length > 0;
const canRevise = form.Decision === 'Rejected' && hasComment && revisionCount < maxRevisions;

return [{
  json: {
    ...form,
    revisionCount,
    maxRevisions,
    hasComment,
    canRevise
  }
}];

const form = $input.item.json;

const newRevisionCount = (form.revisionCount || 0) + 1;

return [{
  json: {
    isRevision: true,
    previousTestCases: $('AI Test Case Generator').item.json.output.testCases,
    revisionComments: form['Revision Comments'],
    revisionCount: newRevisionCount
  }
}];

const data = $input.item.json;

let comment = `*Test Pack - Approved & Stored*\n\n`;
comment += `*Automated Review:* ${data['Automated Review Verdict'] || ''}\n`;
comment += `*Review Summary:* ${data['Automated Review Summary'] || ''}\n\n`;
comment += `*Revisions before approval:* ${data.revisionCount || 0}\n\n`;
comment += `${data['Test Pack (Test Cases + Test Data)']}\n`;
comment += `\n_This Test Pack was drafted by the AI Test Case/Data Generator agents, reviewed by the AI Review Agent, and approved by a human before being stored on this story. In a production setup, replace this Jira-comment Store step with a push into Zephyr, Testmo, or Xray._`;

return [{
  json: {
    issueKey: data['Jira Issue'].split(' - ')[0].trim(),
    commentBody: comment,
    revisionCount: data.revisionCount || 0
  }
}];

const created = $input.item.json;
const finalPack = $('Finalize Approved Test Pack').item.json;

let md = `**Decision:** Approved\n\n`;
md += `**Stored on:** ${finalPack.issueKey} (as a Jira comment)\n\n`;
md += `**Revisions before approval:** ${finalPack.revisionCount}\n\n`;
md += `${finalPack.commentBody}`;

return [{
  json: {
    output: md,
    decision: 'Approved',
    issueKey: finalPack.issueKey,
    revisionCount: finalPack.revisionCount
  }
}];

const data = $input.item.json;

let md = `**Decision:** Rejected\n\n`;

if (data.revisionCount >= data.maxRevisions) {
  md += `Maximum revision attempts (${data.maxRevisions}) reached without approval. This Test Pack needs manual handling outside this workflow.\n\n`;
} else if (!data.hasComment) {
  md += `The Test Pack was rejected with no revision comments, so it was not sent back for AI revision. Nothing was stored on the Jira issue.\n\n`;
}

md += `**Jira Issue:** ${data['Jira Issue']}\n\n`;
md += `**Last Automated Review Verdict:** ${data['Automated Review Verdict']}\n\n`;
md += `**Revisions used:** ${data.revisionCount} of ${data.maxRevisions}\n\n`;
md += `_To try again, start a new run referencing the same story, or hand this off for manual test design._`;

return [{
  json: {
    output: md,
    decision: 'Rejected',
    revisionCount: data.revisionCount
  }
}];
